const loginIdentityCreateNewUserAndPasswordLoginIdentity = `-- name: LoginIdentityCreateNewUserAndPasswordLoginIdentity :one
WITH
  new_user AS (
    INSERT INTO
      users (username, role_name)
    VALUES
      (
        $1::text,
        $2::text
      )
    RETURNING
      id, username, role_name, blocked_at, blocked_until, deleted_at, created_at, updated_at
  ),
  new_user_info AS (
    INSERT INTO
      user_info (profile_image, first_name, last_name)
    VALUES
      (
        $3::text,
        $4::text,
        $5::text
      )
    RETURNING
      id, profile_image, first_name, last_name, updated_at
  ),
  new_identity AS (
    INSERT INTO
      login_identity (user_id, identity_type)
    VALUES
      (
        (
          SELECT
            id
          FROM
            new_user
        ),
        $6::text
      )
    RETURNING
      id
  ),
  final_insert AS (
    INSERT INTO
      password_login_identity (
        login_identity_id,
        email,
        phone,
        hashed_pass,
        pass_salt,
        verified_at
      )
    VALUES
      (
        (
          SELECT
            id
          FROM
            new_identity
        ),
        $7::text,
        $8::text,
        $9::text,
        $10::text,
        $11::timestamptz
      )
  )
SELECT
  new_user.id, username, role_name, blocked_at, blocked_until, deleted_at, created_at, new_user.updated_at, new_user_info.id, profile_image, first_name, last_name, new_user_info.updated_at
FROM
  new_user,
  new_user_info
`

